describe('User Profile - Active Sessions', () => {
    beforeEach(() => {
        cy.login(); // Assuming a custom command for login
        cy.visit('/user/profile/sessions'); // Navigate to the active sessions page
    });

    it('should display all active sessions', () => {
        cy.get('.session-list').should('be.visible');
        cy.get('.session-item').should('have.length.greaterThan', 0); // Check that there are active sessions
        cy.get('.session-item').first().should('contain', 'Active Session'); // Check for expected text in the first session
    });

    it('should log out of a specific session', () => {
        cy.get('.session-item').first().within(() => {
            cy.get('.logout-button').click(); // Click the logout button for the first session
        });
        cy.get('.notification').should('contain', 'Successfully logged out of the session'); // Verify logout success message
        cy.get('.session-item').should('have.length.lessThan', 1); // Check that the session list has updated
    });
});
